pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        bytes32 someAssertionId = identifier;
        bool ok;
        try c.assertionDisputedCallback(someAssertionId) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.prank(caller);
        bool callSucceeded;
        try c.requestPrice(identifier, time, ancillaryData) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        if (caller != address(this)) {
            assertTrue(!callSucceeded);
        } else {
            assertTrue(callSucceeded);
        }
    }
}
